 for(const [type,pose] of Object.entries({reprime:'reprime',repair:'repair',heal:'heal',loot:'loot',equipLoot:'equip',weapon:'equip',door:'door',breach:'breach',throwTorch:'throw-torch',boleadoras:'throw-bolas',free:'free',ration:'use-supplies',artillery:'artillery-fire',artilleryReload:'artillery-reload',artilleryMove:'artillery-move',artilleryPivot:'artillery-pivot',overwatch:'aim-idle',brace:'brace-idle'})){
  const selected=spriteOrderPose({type},unit,unit);assert.equal(selected,pose);
  assert.equal(selectSprite(unit,{moving:false},selected,'civilian').name,`civilian-${pose}`);
 }
